<script setup>
import { onMounted, proxyRefs, ref } from 'vue';import { useStockReceipts } from '../../../composables/useStockReceipts';const stock=proxyRefs(useStockReceipts());const selected=ref(''),employee=ref(''),remarks=ref('');onMounted(()=>stock.load());
async function confirm(row){if(await stock.confirm(row,employee.value,remarks.value)){selected.value='';employee.value='';remarks.value='';}}
</script>
<template><section class="stock-panel"><div class="stock-panel-head"><div><h2>Branch Receipts</h2><p>Released transfers awaiting branch receipt confirmation.</p></div><button :disabled="stock.loading" @click="stock.load({force:true})">{{stock.loading?'Loading…':'↻ Refresh'}}</button></div><label class="stock-search">Search receipts<input v-model="stock.query" type="search" placeholder="Stock entry, warehouse, or status"></label><p v-if="stock.error" class="stock-error">{{stock.error}}</p><p v-if="stock.loading" class="stock-loading">Loading branch receipts…</p><div class="stock-table-wrap"><table><thead><tr><th>Stock entry</th><th>Warehouse</th><th>Released</th><th>Released by</th><th>Items</th><th>Status</th><th>Actions</th><th>ERP</th></tr></thead><tbody><template v-for="row in stock.rows" :key="row.name"><tr><td>{{row.name}}</td><td>{{row.set_warehouse||'—'}}</td><td>{{String(row.posting_date||row.creation||'').slice(0,10)||'—'}}</td><td>{{row.released_by||'—'}}</td><td>{{(row.items||[]).length}}</td><td><span class="stock-status">{{row.workflow_state||row.status||'—'}}</span></td><td><button @click="selected=selected===row.name?'':row.name">{{selected===row.name?'Close':'Confirm receipt'}}</button></td><td><a class="stock-document-link" :href="`/app/stock-entry/${encodeURIComponent(row.name)}`" target="_blank" rel="noopener">Open</a></td></tr><tr v-if="selected===row.name" class="stock-detail"><td colspan="8"><div class="stock-table-wrap"><table><thead><tr><th>Item</th><th>Released qty</th></tr></thead><tbody><tr v-for="item in row.items||[]" :key="item.name"><td>{{item.item_name||item.item_code}}</td><td>{{item.qty}}</td></tr></tbody></table></div><div class="stock-form-grid"><label>Receiving employee ID<input v-model="employee" placeholder="Employee ID"></label><label class="stock-form-wide">Receipt remarks<textarea v-model="remarks" rows="2"></textarea></label></div><button class="stock-primary" :disabled="stock.busy" @click="confirm(row)">{{stock.busy?'Saving…':'Confirm & submit receipt'}}</button></td></tr></template><tr v-if="!stock.loading&&!stock.rows.length"><td colspan="8" class="stock-empty">No open branch receipts.</td></tr></tbody></table></div></section></template>
